package ama.transcript;
import ama.config.ConfigArchiveSource;import ama.contract.IdentityContracts.Actor;import ama.contract.MinutesContracts.*;import ama.contract.TaskContracts.SubjectRef;import java.util.*;import java.util.function.Supplier;import org.springframework.jdbc.core.JdbcTemplate;import static ama.contract.MinutesContracts.*;import static ama.contract.MinutesContracts.FailureCode.*;
/** Controlled actual S/A/F composition; formal new effects await the combined publication installation. */
public final class JdbcMinutesSavedCommands {
 private final JdbcTranscriptAuthority authority;private final Supplier<ConfigArchiveSource.Snapshot> archives;private final String pin;private final TranscriptAcquisitionBudget limits;private final JdbcMinutesCommandReceipts receipts;private final JdbcTemplate j;
 public JdbcMinutesSavedCommands(JdbcTranscriptAuthority authority,Supplier<ConfigArchiveSource.Snapshot> archives,String pin,TranscriptAcquisitionBudget limits){this.authority=Objects.requireNonNull(authority);this.archives=Objects.requireNonNull(archives);hash(pin);this.pin=pin;this.limits=Objects.requireNonNull(limits);receipts=new JdbcMinutesCommandReceipts(authority.dataSource(),authority.transactionRunner(),authority.savedAccess());j=new JdbcTemplate(authority.dataSource());j.setQueryTimeout(2);}
 private record AdoptPlan(MinutesGraphCapture.Graph graph,MinutesSavedGraphPlan copy,String candidate,String input,String fingerprint){}
 public Map<String,Object> adopt(Actor actor,String meeting,String key,long expected,String candidate,String input,String fingerprint,String trace){
  JdbcMinutesFactsReader.independent();uuid(candidate);uuid(input);uuid(trace);hash(fingerprint);var identity=JdbcMinutesCommandReceipts.identity(actor,meeting,"MINUTES_ADOPT",key,expected,candidate,input,fingerprint);var replay=receipts.lookup(actor,meeting,identity);if(replay.isPresent())return replay.orElseThrow();
  var budget=limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);MinutesGraphDiscovery.Discovery declaration=null;MinutesGraphCapture.Graph captured=null;AdoptPlan planned=null;RuntimeException error=null;
  try{declaration=MinutesGraphDiscovery.withPending(authority.dataSource(),MinutesGraphDiscovery.discover(authority.dataSource(),meeting,"ADOPT",candidate,limits,authority.readBudget()),limits.tasks());JdbcMinutesFactsReader.charge(declaration,budget);var declared=declaration;captured=authority.transactionRunner().required(()->{var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,declared);var scope=authority.minutesScope(gate,actor,meeting);var graph=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,declared,budget);adoptable(graph,expected,candidate,input,fingerprint);return graph;});
   new JdbcMinutesFactsReader(authority,archives,pin,limits).prepare(captured,budget);var original=candidate(captured,candidate);var copy=MinutesSavedGraphPlan.copy((String)original.get("minutes_revision_id"),(String)original.get("element_set_id"),captured.rows(),(String)captured.discovery().root().get("minutes_revision_id"),actor.enterpriseId(),budget).protectHumanTitle(captured);planned=new AdoptPlan(captured,copy,candidate,input,fingerprint);
  }catch(RuntimeException failure){if(Thread.currentThread().isInterrupted()||failure instanceof Failure f&&f.code()==CANCELLED)throw failure;error=failure;}
  final var selected=declaration;final var plan=planned;final var failed=error;
  return authority.transactionRunner().required(()->{var stored=receipts.claim(actor,meeting,identity);var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,selected);JdbcMinutesCommandReceipts.match(stored);if(stored.result()!=null)return receipts.restore(meeting,identity,stored,true);if(failed!=null)throw failed;
   var scope=authority.minutesScope(gate,actor,meeting);var fresh=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,selected,budget);require(fresh.equals(plan.graph()),PROVENANCE_UNAVAILABLE);adoptable(fresh,expected,candidate,input,fingerprint);authority.claimMinutesWrite(scope,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.ADOPT,plan,candidate);
   var writer=new MinutesSavedWriter(authority);writer.writeAndReadback(scope,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.ADOPT,plan,plan.copy().rows(MinutesHistorySlots.next(fresh,"minutes_revision",1),MinutesHistorySlots.next(fresh,"element_set",1)),plan.copy(),budget);
   require(j.update("UPDATE generation_candidate SET state='ADOPTED',decided_at=UTC_TIMESTAMP(6) WHERE id=? AND meeting_id=? AND state='PENDING' AND base_revision=?",candidate,meeting,expected)==1,PROVENANCE_UNAVAILABLE);writer.advance(scope,gate,actor,fresh,plan.copy(),fingerprint,expected+1);receipts.accepted(identity,candidate);var response=receipts.restore(meeting,identity,new JdbcMinutesCommandReceipts.Stored(candidate,200,true),false);
   new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(actor.enterpriseId(),"MINUTES_ADOPTED",meeting,expected+1,"SUCCEEDED",trace,java.time.Instant.now()));var outbox=new ama.task.JdbcOutbox(authority.dataSource(),new MinutesEventReferences(authority.dataSource()).validators());outbox.append(new ama.contract.OutboxContracts.EventDraft("MINUTES_ADOPTED",null,new SubjectRef("MEETING",meeting),expected+1,new ama.contract.OutboxContracts.Reference("MINUTES_REVISION",plan.copy().body())));outbox.flush();return response;
  });
 }
 public record Reanchor(String evidenceId,long start,long end){public Reanchor{uuid(evidenceId);if(start<0||end<=start||end>Long.MAX_VALUE-1)throw new IllegalArgumentException("Invalid scalar anchor");}}
 private record BodyPlan(MinutesGraphCapture.Graph graph,MinutesSavedGraphPlan copy){}
 public Map<String,Object> saveBody(Actor actor,String meeting,String key,long expected,String sourceRevision,String title,String body,List<Reanchor> anchors,String trace){
  JdbcMinutesFactsReader.independent();uuid(sourceRevision);uuid(trace);Objects.requireNonNull(title);Objects.requireNonNull(body);scalars(title);scalars(body);if(body.isBlank())throw new ama.contract.TranscriptContracts.Failure(422,"BODY_REQUIRED");var normalized=new ArrayList<>(Objects.requireNonNull(anchors));normalized.sort(Comparator.comparing(Reanchor::evidenceId));if(normalized.stream().map(Reanchor::evidenceId).distinct().count()!=normalized.size())throw new ama.contract.TranscriptContracts.Failure(422,"COMPLETE_REANCHORS_REQUIRED");var semantics=new ArrayList<String>(List.of(sourceRevision,title,body));for(var anchor:normalized){semantics.add(anchor.evidenceId());semantics.add(Long.toString(anchor.start()));semantics.add(Long.toString(anchor.end()));}var identity=JdbcMinutesCommandReceipts.identity(actor,meeting,"MINUTES_BODY_SAVE",key,expected,semantics.toArray(String[]::new));var replay=receipts.lookup(actor,meeting,identity);if(replay.isPresent())return replay.orElseThrow();
  var budget=limits.ledger(authority.readBudget(),authority.canonicalBudget(),()->false);MinutesGraphDiscovery.Discovery declaration=null;BodyPlan planned=null;RuntimeException error=null;
  try{declaration=MinutesGraphDiscovery.withPending(authority.dataSource(),MinutesGraphDiscovery.discover(authority.dataSource(),meeting,"BODY_EDIT",sourceRevision,limits,authority.readBudget()),limits.tasks());JdbcMinutesFactsReader.charge(declaration,budget);var declared=declaration;var captured=authority.transactionRunner().required(()->{var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,declared);var scope=authority.minutesScope(gate,actor,meeting);var graph=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,declared,budget);bodyWritable(graph,expected,sourceRevision);return graph;});new JdbcMinutesFactsReader(authority,archives,pin,limits).prepare(captured,budget);
   var wanted=JdbcMinutesFactsReader.rows(captured,Table.EVIDENCE_LINK).stream().filter(row->sourceRevision.equals(row.nullableString("minutes_revision_id"))).map(row->row.string("id")).sorted().toList();if(!wanted.equals(normalized.stream().map(Reanchor::evidenceId).toList()))throw new ama.contract.TranscriptContracts.Failure(422,"COMPLETE_REANCHORS_REQUIRED");var byId=new HashMap<String,Reanchor>();for(var anchor:normalized)byId.put(anchor.evidenceId(),anchor);var edited=new ArrayList<FullRow>();for(var row:captured.rows()){var cells=new ArrayList<>(row.cells());if(row.table()==Table.MINUTES_REVISION&&sourceRevision.equals(row.string("id"))){cells.set(row.table().index("body"),cell(body));cells.set(row.table().index("title"),cell(title));cells.set(row.table().index("title_origin"),cell("HUMAN"));}else if(row.table()==Table.EVIDENCE_LINK&&sourceRevision.equals(row.nullableString("minutes_revision_id"))){var anchor=byId.get(row.string("id"));String canonical=ama.minutes.contract.OutputValidation.anchorText(ama.minutes.contract.OutputValidation.anchor(body,anchor.start(),anchor.end(),()->false));cells.set(row.table().index("target_anchor"),cell(canonical));}edited.add(new FullRow(row.table(),cells));}
   planned=new BodyPlan(captured,MinutesSavedGraphPlan.copy(sourceRevision,null,edited,sourceRevision,actor.enterpriseId(),budget));
  }catch(RuntimeException failure){if(Thread.currentThread().isInterrupted()||failure instanceof Failure f&&f.code()==CANCELLED)throw failure;error=failure;}
  final var selected=declaration;final var plan=planned;final var failed=error;return authority.transactionRunner().required(()->{var stored=receipts.claim(actor,meeting,identity);var gate=JdbcMinutesFactsReader.lockGraph(authority,actor,meeting,selected);JdbcMinutesCommandReceipts.match(stored);if(stored.result()!=null)return receipts.restore(meeting,identity,stored,true);if(failed!=null)throw failed;var scope=authority.minutesScope(gate,actor,meeting);var fresh=MinutesGraphCapture.captureCurrent(authority,scope,gate,actor,selected,budget);require(fresh.equals(plan.graph()),PROVENANCE_UNAVAILABLE);bodyWritable(fresh,expected,sourceRevision);authority.claimMinutesWrite(scope,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.EDIT,plan);var writer=new MinutesSavedWriter(authority);writer.writeAndReadback(scope,gate,actor,fresh,JdbcTranscriptAuthority.MinutesWritePurpose.EDIT,plan,plan.copy().rows(MinutesHistorySlots.next(fresh,"minutes_revision",1),1),plan.copy(),budget);writer.advanceEdit(scope,gate,actor,fresh,plan,plan.copy(),expected+1);receipts.accepted(identity,plan.copy().body());var response=receipts.restore(meeting,identity,new JdbcMinutesCommandReceipts.Stored(plan.copy().body(),200,true),false);
   new ama.audit.JdbcAuditAdapter(authority.dataSource()).append(new ama.contract.AuditContracts.AuditEvent(actor.enterpriseId(),"MINUTES_SAVED",meeting,expected+1,"SUCCEEDED",trace,java.time.Instant.now()));var outbox=new ama.task.JdbcOutbox(authority.dataSource(),new MinutesEventReferences(authority.dataSource()).validators());outbox.append(new ama.contract.OutboxContracts.EventDraft("MINUTES_SAVED",null,new SubjectRef("MEETING",meeting),expected+1,new ama.contract.OutboxContracts.Reference("MINUTES_REVISION",plan.copy().body())));outbox.flush();return response;
  });
 }
 public record ActionFields(String ownerEnterpriseId,String ownerDisplay,String dueOn){}
 public Map<String,Object> saveElement(Actor actor,String meeting,String key,long expected,String sourceSet,String element,String body,List<Reanchor> anchors,String trace){throw new ama.contract.TranscriptContracts.Failure(503,"SET_EDIT_NOT_INSTALLED");}
 public Map<String,Object> saveActionFields(Actor actor,String meeting,String key,long expected,String sourceSet,String element,ActionFields fields,String trace){throw new ama.contract.TranscriptContracts.Failure(503,"ACTION_EDIT_NOT_INSTALLED");}
 public Map<String,Object> openQuestion(Actor actor,String meeting,String key,long expected,String sourceSet,String element,String body,List<Reanchor> anchors,String trace){throw new ama.contract.TranscriptContracts.Failure(503,"CONVERSION_NOT_INSTALLED");}
 public Map<String,Object> restoreBody(Actor actor,String meeting,String key,long expected,String source,String trace){throw new ama.contract.TranscriptContracts.Failure(503,"RESTORE_NOT_INSTALLED");}
 public Map<String,Object> restoreSet(Actor actor,String meeting,String key,long expected,String source,String trace){throw new ama.contract.TranscriptContracts.Failure(503,"RESTORE_NOT_INSTALLED");}
 private static void bodyWritable(MinutesGraphCapture.Graph graph,long expected,String source){var root=graph.discovery().root();if(((Number)root.get("revision")).longValue()!=expected||!source.equals(root.get("minutes_revision_id")))throw new ama.contract.TranscriptContracts.Failure(409,"REVISION_CONFLICT");if(expected>=Long.MAX_VALUE-1)throw new ama.contract.TranscriptContracts.Failure(409,"REVISION_EXHAUSTED");if(graph.auxiliary().getOrDefault("generation_candidate",List.of()).stream().anyMatch(row->source.equals(row.get("minutes_revision_id"))))throw new ama.contract.TranscriptContracts.Failure(422,"SAVED_REVISION_REQUIRED");var guard=graph.auxiliary().getOrDefault("meeting_minutes_editor_guard",List.of());if(guard.size()!=1||((Number)guard.getFirst().get("intent_epoch")).longValue()<=0)throw new ama.contract.TranscriptContracts.Failure(409,"EDITOR_INTENT_REQUIRED");require(((Number)root.get("ever_published")).intValue()==0&&"ACTIVE".equals(root.get("lifecycle"))&&"ACTIVE".equals(root.get("governance_state"))&&!"PUBLISHED".equals(root.get("stage")),CAPABILITY_UNAVAILABLE);}

 private static Map<String,Object> candidate(MinutesGraphCapture.Graph graph,String id){var found=graph.auxiliary().getOrDefault("generation_candidate",List.of()).stream().filter(row->id.equals(row.get("id"))).toList();require(found.size()==1,PROVENANCE_UNAVAILABLE);return found.getFirst();}
 private static void adoptable(MinutesGraphCapture.Graph graph,long expected,String id,String inputId,String fingerprint){var root=graph.discovery().root();JdbcMinutesGenerationPreparation.writable(root,expected);if(expected>=Long.MAX_VALUE-1)throw new ama.contract.TranscriptContracts.Failure(409,"REVISION_EXHAUSTED");var c=candidate(graph,id);if(!"PENDING".equals(c.get("state"))||((Number)c.get("base_revision")).longValue()!=expected)throw new ama.contract.TranscriptContracts.Failure(409,"CANDIDATE_NOT_CURRENT");require(inputId.equals(c.get("input_id"))&&fingerprint.equals(c.get("input_fingerprint")),PROVENANCE_UNAVAILABLE);var input=JdbcMinutesFactsReader.one(graph,Table.GENERATION_INPUT,inputId);for(String key:List.of("transcript_confirmation_id","template_revision_id","exclusion_revision_id","element_set_id"))require(Objects.equals(input.nullableString(key),root.get(key)),PROVENANCE_UNAVAILABLE);var tasks=graph.auxiliary().getOrDefault("durable_task",List.of()).stream().filter(row->c.get("task_id").equals(row.get("id"))).toList();require(tasks.size()==1,PROVENANCE_UNAVAILABLE);var task=tasks.getFirst();require("SUCCEEDED".equals(task.get("state"))&&"GENERATION_CANDIDATE".equals(task.get("output_kind"))&&id.equals(task.get("output_id"))&&inputId.equals(task.get("input_id"))&&fingerprint.equals(task.get("input_fingerprint"))&&((Number)task.get("business_version")).longValue()==expected&&Objects.equals(task.get("cancel_epoch"),root.get("cancel_epoch")),PROVENANCE_UNAVAILABLE);}
}
